SELECT  FROM orders 
WHERE create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY create_time DESC

SELECT FROM orders
AND (order_no LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(goods_description, '') LIKE CONCAT('%', #{keyword}, '%'))
