UPDATE orders 
SET is_exception = 1, exception_type = #{exceptionType}, update_time = NOW() 
WHERE id = #{id}

UPDATE orders
SET is_exception = 0, exception_type = NULL, update_time = NOW()
WHERE id = #{id}

UPDATE orders
SET courier_id = NULL, dispatch_type = NULL, update_time = NOW()
WHERE id = #{id}
